def canonical(value):return ALIASES.get(str(value).strip().lower(),str(value).strip().lower())
def language_name(value):return next((name for code,name,_ in LANGUAGES if code==canonical(value)),value)
def catalog():return [{'code':code,'name':name,'native':native} for code,name,native in LANGUAGES]
